import{_ as n,a0 as s,w as i,s as l,ao as d,I as a,x as e,a1 as r,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"dupeGuru - 直接从硬盘中查找并移除重复文件 | LCTT x X-CMD","titleTemplate":false,"description":"dupeGuru - 直接从硬盘中查找并移除重复文件 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"dupeGuru - 直接从硬盘中查找并移除重复文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"dupeGuru - 直接从硬盘中查找并移除重复文件 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive","title":"dupeGuru - 直接从硬盘中查找并移除重复文件","tag":"201503","desc":""},"relativePath":"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive.md","filePath":"[post].md"}'),o={name:"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive.md"};function g(h,u,m,b,G,f){const t=s("Link");return i(),l("div",null,[u[20]||(u[20]=d('<h1 id="dupeguru-直接从硬盘中查找并移除重复文件" tabindex="-1">dupeGuru - 直接从硬盘中查找并移除重复文件 <a class="header-anchor" href="#dupeguru-直接从硬盘中查找并移除重复文件" aria-label="Permalink to “dupeGuru - 直接从硬盘中查找并移除重复文件”">​</a></h1><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>对我们来说，磁盘被装满是棘手问题之一。无论我们如何小心谨慎，我们总可能将相同的文件复制到多个不同的地方，或者在不知情的情况下，重复下载了同一个文件。因此，迟早你会看到“磁盘已满”的错误提示，若此时我们确实需要一些磁盘空间来存储重要数据，以上情形无疑是最糟糕的。假如你确信自己的系统中有重复文件，那么 <strong>dupeGuru</strong> 可能会帮助到你。</p><p>dupeGuru 团队也开发了名为 <strong>dupeGuru 音乐版</strong> 的应用来移除重复的音乐文件，和名为 <strong>dupeGuru 图片版</strong> 的应用来移除重复的图片文件。</p><h3 id="_1-dupeguru-标准版" tabindex="-1">1. dupeGuru (标准版) <a class="header-anchor" href="#_1-dupeguru-标准版" aria-label="Permalink to “1. dupeGuru (标准版)”">​</a></h3>',5)),a("p",null,[u[1]||(u[1]=e("需要告诉那些不熟悉 ",-1)),r(t,{href:"http://www.hardcoded.net/dupeguru/"},{default:p(()=>[...u[0]||(u[0]=[e("dupeGuru",-1)])]),_:1}),u[2]||(u[2]=e(" 的人，它是一个免费、开源、跨平台的应用，其用途是在系统中查找和移除重复文件。它可以在 Linux, Windows, 和 Mac OS X 等平台下使用。通过使用一个快速的模糊匹配算法，它可以在几分钟内找到重复文件。同时，你还可以调整 dupeGuru 使它去精确查找特定文件类型的重复文件，以及从你想删除的文件中，清除某种文件。它支持英语、 法语、 德语、 中文 （简体）、 捷克语、 意大利语、亚美尼亚语、俄语、乌克兰语、巴西语和越南语。",-1))]),u[21]||(u[21]=d(`<h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru”">​</a></h4><p>dupeGuru 开发者已经构建了一个 Ubuntu PPA (Personal Package Archives)来简化安装过程。想要安装 dupeGuru，依次在终端中键入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:hsoft/ppa</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install dupeguru-se</span></span></code></pre></div><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>使用非常简单，可从 Unity 面板或菜单中启动 dupeGuru。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru_007.png" alt=""></p><p>点击位于底部的 <code>+</code> 按钮来添加你想扫描的文件目录。点击 <code>扫描</code> 按钮开始查找重复文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru_008.png" alt=""></p><p>一旦所选目录中含有重复文件，那么它将在窗口中展示重复文件。正如你所看到的，在下面的截图中，我的下载目录中有一个重复文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Results_009.png" alt=""></p><p>现在，你可以决定下一步如何操作。你可以删除这个重复的文件，或者对它进行重命名，抑或是 复制/移动 到另一个位置。为此，选定该重复文件，或在菜单栏中选定写有“<strong>仅显示重复</strong>”选项 ，如果你选择了“<strong>仅显示重复</strong>”选项，则只有重复文件在窗口中可见，这样你便可以轻松选择并删除这些文件。点击“操作”下拉菜单，最后选择你将执行的操作。在这里，我只想删除重复文件，所以我选择了“移动标记文件到垃圾箱”这个选项。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/Menu_010.png" alt=""></p><p>接着，点击“继续”选项来移除重复文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/Deletion-Options_011.png" alt=""></p><h3 id="_2-dupeguru-音乐版" tabindex="-1">2. dupeGuru 音乐版 <a class="header-anchor" href="#_2-dupeguru-音乐版" aria-label="Permalink to “2. dupeGuru 音乐版”">​</a></h3>`,15)),a("p",null,[r(t,{href:"http://www.hardcoded.net/dupeguru_me/"},{default:p(()=>[...u[3]||(u[3]=[e("dupeGuru 音乐版",-1)])]),_:1}),u[4]||(u[4]=e(" 或简称 dupeGuru ME，它的功能与 dupeGuru 类似。它拥有 dupeGuru 的所有功能，但它包含更多的信息列 （如比特率，持续时间，标签等）和更多的扫描类型（如带有字段的文件名，标签以及音频内容）。和 dupeGuru 一样，dupeGuru ME 也运行在 Linux、Windows 和 Mac OS X 中。",-1))]),u[22]||(u[22]=d('<p>它支持众多的格式，诸如 MP3、WMA、AAC (iTunes 格式)、OGG、FLAC，以及失真率较少的 AAC 和 WMA 格式等。</p><h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru-me" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru ME <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru-me" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru ME”">​</a></h4><p>现在，我们不必再添加任何 PPA，因为在前面的步骤中，我们已经进行了添加。所以在终端中键入以下命令来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dupeguru-me</span></span></code></pre></div><h3 id="使用-1" tabindex="-1">使用 <a class="header-anchor" href="#使用-1" aria-label="Permalink to “使用”">​</a></h3><p>你可以从 Unity 面板或菜单中启动它。dupeGuru ME 的使用方法、操作界面以及外观和正常的 dupeGuru 类似。添加你想扫描的目录并选择你想执行的操作。重复的音乐文件就会被删除。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Music-Edition-Results_012.png" alt=""></p><h3 id="_3-dupeguru-图片版" tabindex="-1">3. dupeGuru 图片版 <a class="header-anchor" href="#_3-dupeguru-图片版" aria-label="Permalink to “3. dupeGuru 图片版”">​</a></h3>',8)),a("p",null,[r(t,{href:"http://www.hardcoded.net/dupeguru_pe/"},{default:p(()=>[...u[5]||(u[5]=[e("dupeGuru 图片版",-1)])]),_:1}),u[6]||(u[6]=e(",或简称为 duepGuru PE，是一个在你的电脑中查找重复图片的工具。它和 dupeGuru 类似，但独具匹配重复图片的功能。dupeGuru PE 可运行在 Linux、Windows 和 Mac OS X 中。",-1))]),u[23]||(u[23]=d('<p>dupeGuru PE 支持 JPG、PNG、TIFF、GIF 和 BMP 等图片格式。所有的这些格式可以被同时比较。Mac OS X 版的 dupeGuru PE 还支持 PSD 和 RAW (CR2 和 NEF) 格式。</p><h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru-pe" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru PE <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安装-dupeguru-pe" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安装 dupeGuru PE”">​</a></h4><p>由于我们已经添加了 PPA，我们也不必为 dupeGuru PE 再次添加。只需运行如下命令来安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dupeguru-pe</span></span></code></pre></div><h4 id="使用-2" tabindex="-1">使用 <a class="header-anchor" href="#使用-2" aria-label="Permalink to “使用”">​</a></h4><p>就使用方法，操作界面和外观而言，它与 dupeGuru，dupeGuru ME 类似。我就纳闷为什么开发者为不同的类别开发了不同的版本。我想如果开发一个结合以上三个版本功能的应用，或许会更好。</p><p>启动它，添加你想扫描的目录，并选择你想执行的操作。就这样，你的重复文件将被清除。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Picture-Edition-Results_014.png" alt=""></p><p>如果因为任何的安全问题而不能移除某些重复文件，请记下这些文件的位置，通过终端或文件管理器来手动删除它们。</p><p>欢呼吧！</p><hr>',11)),a("p",null,[u[8]||(u[8]=e("via: ",-1)),r(t,{href:"http://www.unixmen.com/dupeguru-find-remove-duplicate-files-instantly-hard-drive/"},{default:p(()=>[...u[7]||(u[7]=[e("http://www.unixmen.com/dupeguru-find-remove-duplicate-files-instantly-hard-drive/",-1)])]),_:1})]),a("p",null,[u[12]||(u[12]=e("作者：",-1)),r(t,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...u[9]||(u[9]=[e("SK",-1)])]),_:1}),u[13]||(u[13]=e(" 译者：",-1)),r(t,{href:"https://github.com/FSSlc"},{default:p(()=>[...u[10]||(u[10]=[e("FSSlc",-1)])]),_:1}),u[14]||(u[14]=e(" 校对：",-1)),r(t,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...u[11]||(u[11]=[e("Caroline",-1)])]),_:1})]),a("p",null,[u[17]||(u[17]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...u[15]||(u[15]=[e("LCTT",-1)])]),_:1}),u[18]||(u[18]=e(" 原创翻译，",-1)),r(t,{href:"http://linux.cn/"},{default:p(()=>[...u[16]||(u[16]=[e("Linux中国",-1)])]),_:1}),u[19]||(u[19]=e(" 荣誉推出",-1))])])}const T=n(o,[["render",g]]);export{P as __pageData,T as default};
